INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Build and Continuously Improve Agents That Work in Production (with Agents)', 'Triangle Tech Talks', 'Tech & Software', '# **Frontier models are more capable than ever. So why do so many agents still fall over in production?** There''s still a big gap between', '# **Frontier models are more capable than ever. So why do so many agents still fall over in production?** There''s still a big gap between what a model can do in a demo and what an agent can reliably deliver at scale. Join Triangle Tech Talks for a practical session on why that gap exists and how teams are closing it. **About the talk** **Marc Klingen**, Co-Founder of **Langfuse**, will cover the real challenges of turning capable models into useful agents: tool use, reliability, evaluation, More info: https://www.meetup.com/triangletechtalks/events/316685081/', '2026-10-15T17:00:00-04:00', '3000 Centregreen Way', '3000 Centregreen Way', 'Cary', 'NC', '', 35.81, -78.8, 'Triangle Tech Talks', 173, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/triangletechtalks/events/316685081/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
